    "questionAr": "متغير عشوائي $X$ متوسطه $\\mu = 50$ وانحرافه المعياري $\\sigma = 4$. باستخدام متباينة تشيبيشيف، أوجد الحد الأدنى المضمون لاحتمال وقوع $X$ في نطاق $k = 2$ انحرافات معيارية حول متوسطه ($|X - 50| < 8$).",
