      "Denominator: Total probability $P(D) = 0.032$.",
      "Bayes' Formula: $P(M_2 \\mid D) = \\frac{0.020}{0.032} = \\frac{20}{32} = \\frac{5}{8} = 0.625$ ($62.5\\%$)."
