      "2. Apply Eve's Law: $\\text{Var}(S) = \\mathbb{E}[\\text{Var}(S|N)] + \\text{Var}(\\mathbb{E}[S|N])$.",
      "3. $\\text{Var}(S) = \\mathbb{E}[N \\sigma^2] + \\text{Var}(N \\mu) = \\lambda \\sigma^2 + \\lambda \\mu^2 = \\lambda (\\sigma^2 + \\mu^2) = \\lambda \\mathbb{E}[X^2]$.",
      "4. Substitute $\\lambda = 7$: $\\text{Var}(S) = (7)(13) = 91$."
