    "questionAr": "مقامر يبدأ برصيد 20 وحدة ويلعب لعبة عادلة (احتمال ربح وحدة واحدة هو $0.5$ وخسارة وحدة هو $0.5$) حتى يصل إلى 100 وحدة أو يفلس (رصيد $0$). ما احتمال إفلاسه في نهاية المطاف؟",
